      "specs_summary": [
        "งานหลังคาผ้าใบแรงดึงสูง (Tension Membrane) โครงเหล็กกัลวาไนซ์ รับประกันโครงสร้าง",
        "วัสดุรับน้ำสระว่ายน้ำ ไวนิลไลเนอร์ (PVC Liner) หนา 1.50 มม. ชนิดเสริมใยพิเศษ ลายกระเบื้องโมเสค โทนฟ้า-น้ำเงิน",
        "งานปูขอบสระว่ายน้ำ หินแกรนิตดำพ่นทราย ขนาด 27 ซม. พร้อมตะแกรงน้ำล้น ABS 25 ซม.",
        "ระบบสระว่ายน้ำ: งานท่อ-ข้อต่อ UPVC 13.5, วาล์วปีกผีเสื้อ 3 นิ้ว, บอลวาล์วยูเนี่ยน, เช็ควาล์ว, ไฟ LED สระน้ำ",
        "ระบบปรับอากาศ Central Air รุ่น CFH-32IVSA Inverter เบอร์ 5 แบรนด์ไทย MiT (>60%) รวม 5 เครื่อง",
        "งานปรับปรุงห้อง Fitness: แผ่นฝ้าอะคูสติก SCG ยิปซัมตราช้าง 72 แผ่น, พื้นกระเบื้องยางไวนิล, กระจกเงาติดผนัง",
        "งานปรับปรุงลานอเนกประสงค์: รื้อทางเท้า, ลงทรายถม, วางตะแกรงเหล็ก 6 มม., เทคอนกรีตหนา 0.15 ม. (45 ลบ.ม.)",
        "งานระบบระบายน้ำ: รางระบายน้ำ คสล. ฝาตะแกรงเหล็ก, บ่อพักดักตะกอน, ท่อ คสล. 0.50 ม. (8 ม.)"
      ],
      "specsSummary": "1. ปรับปรุงอาคารกีฬาในร่ม (ทาสี 517 ตร.ม., ซ่อมกระจก, ห้องน้ำ, พื้นไวนิล 2 มม.) 2. ปรับปรุงสระว่ายน้ำ 406 ตร.ม. (ปูไวนิลไลเนอร์ 1.50 มม., ขอบหินแกรนิตดำ 75 ม., ระบบท่อ UPVC, หลังคาคลุมสระผ้าใบแรงดึงสูง) 3. ปรับปรุงอาคารกิจกรรม 4. ปรับปรุงลานอเนกประสงค์ 5. ครุภัณฑ์เครื่องปรับอากาศ",
